// Browser: consume SDK streaming response with for-await-of
const res = await client.streamChat(...);
for await (const chunk of harmonizer.toAsyncIterator(res.body, { signal })) {
  renderToken(chunk);
}

// Browser: pipeline into a Response for streaming fetch consumers
const res = await client.streamEvals(...);
const rs = harmonizer.fromAsyncIterator(harmonizer.toAsyncIterator(res.body), { frame: 'jsonl' });
return new Response(rs, { headers: { 'Content-Type': 'text/event-stream' } });

// Node: reconnect-on-failure with resume token
const factory = (resumeToken) => client.streamChat({ prompt, resumeToken });
const rs = harmonizer.retryResume(factory, { maxAttempts: 5 });
for await (const chunk of harmonizer.toAsyncIterator(rs)) console.log(chunk.text);

// Example: persisting checkpoints to improve resume safety
let lastCheckpoint = null;
const { stream } = await harmonizer.wrapSdkResponse(res, { checkpointEvery: 100, onCheckpoint: (t) => { lastCheckpoint = t; } });
// on transient failure use lastCheckpoint in subsequent factory call
